// Integration: `refilm fit` — does it recover a known easing from a curve?
//
// The series below is generated by evaluating cubic-bezier(0.22, 1, 0.36, 1)
// over 900ms and scaling to a 40px travel. That is exactly the curve the
// fade-up fixture declares, so a correct fit must name that bezier (or its
// close family) and a duration within 5% of 900ms.
//
// The expected points are computed here from the bezier definition rather than
// copied from a fit output, so the test cannot agree with a bug by construction.

import test from "node:test";
import assert from "node:assert/strict";
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpDir, cleanup, runCli, parseEnvelope } from "../helpers.js";

/** CSS cubic-bezier evaluation: solve x(u) = t for u, then return y(u). */
function cubicBezier(p1x, p1y, p2x, p2y) {
  const cx = 3 * p1x;
  const bx = 3 * (p2x - p1x) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * p1y;
  const by = 3 * (p2y - p1y) - cy;
  const ay = 1 - cy - by;
  const sampleX = (u) => ((ax * u + bx) * u + cx) * u;
  const sampleY = (u) => ((ay * u + by) * u + cy) * u;
  return (t) => {
    let lo = 0;
    let hi = 1;
    let u = t;
    for (let i = 0; i < 60; i++) {
      const x = sampleX(u);
      if (Math.abs(x - t) < 1e-7) break;
      if (x < t) lo = u;
      else hi = u;
      u = (lo + hi) / 2;
    }
    return sampleY(u);
  };
}

const BEZIER = [0.22, 1, 0.36, 1];
const DURATION_MS = 900;
const TRAVEL = 40;
const FPS = 25;

/** A [[tMs, value], …] series, rounded to 2dp the way a real track would be. */
function syntheticSeries() {
  const ease = cubicBezier(...BEZIER);
  const points = [];
  for (let ms = 0; ms <= DURATION_MS; ms += 1000 / FPS) {
    const t = Math.min(1, ms / DURATION_MS);
    points.push([Math.round(ms), Math.round(ease(t) * TRAVEL * 100) / 100]);
  }
  return points;
}

test("fit: recovers the bezier family and duration of a known curve within 5%", async () => {
  const series = syntheticSeries();
  const res = await runCli(["fit", "--series", JSON.stringify(series), "--json"], { timeoutMs: 60_000 });
  assert.equal(res.code, 0, `fit should succeed:\n${res.stderr.slice(-2000)}`);

  const env = parseEnvelope(res, "fit");
  assert.equal(env.ok, true);
  const d = env.data;
  assert.ok(Array.isArray(d.bestFits) && d.bestFits.length > 0, "fit must report at least one candidate");

  const best = d.bestFits[0];
  // ---- the easing family: cubic-bezier(.22,1,.36,1) is a strong ease-out
  assert.equal(best.family, "ease-out", `expected an ease-out family, got ${best.family}`);
  assert.ok(Array.isArray(best.bezier) && best.bezier.length === 4, "the best fit must carry a 4-point bezier");
  assert.equal(typeof best.rmse, "number");

  // ---- the bezier itself, within a sane tolerance
  const tol = 0.08;
  for (let i = 0; i < 4; i++) {
    assert.ok(
      Math.abs(best.bezier[i] - BEZIER[i]) <= tol,
      `bezier[${i}] should be ~${BEZIER[i]}, got ${best.bezier[i]} (full: ${JSON.stringify(best.bezier)})`,
    );
  }

  // ---- the duration, within 5% of 900ms
  const dur = best.durationMs;
  assert.equal(typeof dur, "number", "the fit must report a fitted duration");
  const err = Math.abs(dur - DURATION_MS) / DURATION_MS;
  assert.ok(err <= 0.05, `fitted duration ${dur}ms is outside 5% of ${DURATION_MS}ms (error ${(err * 100).toFixed(1)}%)`);

  // ---- the shape facts a human reads
  assert.ok(Math.abs(d.start - 0) < 1, `start value should be ~0, got ${d.start}`);
  assert.ok(Math.abs(d.end - TRAVEL) < 1, `end value should be ~${TRAVEL}, got ${d.end}`);
  assert.ok(d.visibleDurationMs > 0, "visible duration must be positive");
  assert.equal(typeof d.verdict, "string");
  assert.ok(d.verdict.length > 0);
});

test("fit: a linear series is fitted as linear, not as an ease", async () => {
  // The negative control: a constant-speed ramp must not be reported as ease-out.
  const series = [];
  for (let ms = 0; ms <= 1000; ms += 40) series.push([ms, Math.round((ms / 1000) * 100 * 100) / 100]);

  const res = await runCli(["fit", "--series", JSON.stringify(series), "--json"], { timeoutMs: 60_000 });
  assert.equal(res.code, 0, res.stderr.slice(-1500));
  const d = parseEnvelope(res, "fit linear").data;
  const best = d.bestFits[0];
  assert.equal(best.family, "linear", `a constant ramp must fit linear, got ${best.family}`);
  assert.ok(best.rmse < 0.01, `a perfect linear ramp should fit with a low rmse, got ${best.rmse}`);
});

test("fit: an ease-in series is distinguished from ease-out", async () => {
  // Guards against a fitter that always answers "ease-out".
  const ease = cubicBezier(0.42, 0, 1, 1);
  const series = [];
  for (let ms = 0; ms <= 900; ms += 40) {
    series.push([ms, Math.round(ease(ms / 900) * 100 * 100) / 100]);
  }
  const res = await runCli(["fit", "--series", JSON.stringify(series), "--json"], { timeoutMs: 60_000 });
  assert.equal(res.code, 0, res.stderr.slice(-1500));
  const d = parseEnvelope(res, "fit ease-in").data;
  assert.equal(d.bestFits[0].family, "ease-in", `expected ease-in, got ${d.bestFits[0].family}`);
});

test("fit: --track reads a real track.json and fits a tracked property", async () => {
  // End-to-end: capture the fade-up page with tracking, then fit the tracked
  // translateY curve. This is the path an agent actually uses.
  const dir = tmpDir();
  try {
    const rec = await runCli([
      "record",
      "--url", new URL("../fixtures/fade-up.html", import.meta.url).pathname,
      "--out", dir,
      "--viewport", "640x480",
      "--fps", "25",
      "--duration", "1200",
      "--selector", ".card",
      "--track", ".card",
      "--json",
    ], { timeoutMs: 180_000 });
    assert.equal(rec.code, 0, `record failed:\n${rec.stderr.slice(-2000)}`);

    const res = await runCli([
      "fit",
      "--track", join(dir, "track.json"),
      "--selector", ".card",
      "--prop", "y",
      "--json",
    ], { timeoutMs: 60_000 });
    assert.equal(res.code, 0, `fit --track failed:\n${res.stderr.slice(-2000)}`);
    const d = parseEnvelope(res, "fit track").data;
    assert.ok(d.bestFits.length > 0, "fit must produce candidates from a real track");
    assert.equal(typeof d.start, "number");
    assert.equal(typeof d.end, "number");
    // fade-up moves the card up 40px, so the tracked y must decrease.
    assert.ok(d.end < d.start, `the tracked card should move up: start ${d.start} -> end ${d.end}`);
    const travel = Math.abs(d.end - d.start);
    assert.ok(travel > 20, `expected ~40px of travel, measured ${travel}px`);
  } finally {
    cleanup(dir);
  }
});

test("fit: a malformed series is a usage error with exit 2", async () => {
  const res = await runCli(["fit", "--series", "not-json", "--json"], { timeoutMs: 60_000 });
  assert.equal(res.code, 2, `bad --series should be a usage error, got ${res.code}`);
  const env = parseEnvelope(res, "fit bad series");
  assert.equal(env.ok, false);
  assert.equal(env.errors[0].code, "USAGE");
});

test("fit: no input at all is a usage error, not a silent success", async () => {
  const res = await runCli(["fit", "--json"], { timeoutMs: 60_000 });
  assert.equal(res.code, 2);
  const env = parseEnvelope(res, "fit no input");
  assert.equal(env.ok, false);
  assert.equal(env.errors[0].code, "USAGE");
});

test("fit: --series from a file is accepted", async () => {
  const dir = tmpDir();
  try {
    const p = join(dir, "series.json");
    writeFileSync(p, JSON.stringify(syntheticSeries()));
    const res = await runCli(["fit", "--series", p, "--json"], { timeoutMs: 60_000 });
    // Either form is fine as long as the values come back; if the CLI only takes
    // inline JSON it must say so as a usage error rather than crashing.
    if (res.code === 0) {
      const d = parseEnvelope(res, "fit series file").data;
      assert.ok(d.bestFits.length > 0);
    } else {
      assert.equal(res.code, 2, "an unsupported input form must be a usage error");
      const env = parseEnvelope(res, "fit series file");
      assert.equal(env.ok, false);
    }
  } finally {
    cleanup(dir);
  }
});
